SELECT  #{push} time,area_id area,ip_addr IP,SUM(c2s_byte_len)+SUM(s2c_byte_len) COUNT
FROM traffic_ip_active_statistic
   WHERE stat_time >= #{start}
   AND stat_time < #{end}
GROUP BY ip_addr ,area_id
ORDER BY COUNT desc
LIMIT 10;


select max(stat_time)
  FROM traffic_ip_active_statistic
  WHERE stat_time < #{end}


select max(RECV_TIME)
FROM traffic_netflow_port_info
  WHERE RECV_TIME < #{end}

select entrance_id entrance
from ntc_device_info
group by entrance;
